import { test, expect } from '@playwright/test';

test.describe('Task Management', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tasks');
  });

  test('should delete a task and confirm deletion', async ({ page }) => {
    // Assuming the task to delete has the text 'Sample Task'
    await page.getByText('Sample Task').hover();
    await page.getByRole('button', { name: 'Delete' }).click();

    // Confirm the deletion in the dialog
    await page.getByRole('button', { name: 'Confirm' }).click();

    // Verify the task is deleted
    const task = page.getByText('Sample Task');
    await expect(task).toBeHidden();
  });

  test('should cancel deletion of a task', async ({ page }) => {
    await page.getByText('Sample Task').hover();
    await page.getByRole('button', { name: 'Delete' }).click();

    // Cancel the deletion in the dialog
    await page.getByRole('button', { name: 'Cancel' }).click();

    // Verify the task is still present
    const task = page.getByText('Sample Task');
    await expect(task).toBeVisible();
  });
});
